<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKeyRef;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Service\Visibility\UserPersonalApiKeyVisibilityService;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserPersonalApiKeyRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserPersonalApiKeyVisibilityService $visibility,
        private readonly UserPersonalApiKeyReadGateway $reader
    ) {
    }

    public function allowRetrieve(?UserPersonalApiKeyRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for User personal api key");
        $span = $this->startSpan("Check allow of retrieve usecase for User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?UserPersonalApiKeyRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for User personal api key");
        $span = $this->startSpan("Check hidden fields usecase for User personal api key");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): UserPersonalApiKeyRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for User personal api key");
        $span = $this->startSpan("Run retrieve usecase for User personal api key");
        try {
            $ref = new UserPersonalApiKeyRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve User personal api key');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserPersonalApiKeyRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
